package com.tekwatt.reservation.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="reservations") public class Reservation{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false)private UUID userId;@Column(nullable=false)private UUID chargerId;@Column(nullable=false)private UUID connectorId;@Column(nullable=false,unique=true,length=64)private String reference;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ReservationStatus status;@Column(nullable=false)private Instant startsAt;@Column(nullable=false)private Instant expiresAt;@Column(nullable=false,updatable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;protected Reservation(){}public Reservation(UUID t,UUID u,UUID c,UUID x,String r,Instant s,Instant e){id=UUID.randomUUID();tenantId=t;userId=u;chargerId=c;connectorId=x;reference=r;startsAt=s;expiresAt=e;status=ReservationStatus.ACTIVE;createdAt=Instant.now();updatedAt=createdAt;}public void setStatus(ReservationStatus s){status=s;updatedAt=Instant.now();}public void expireIfNeeded(){if(status==ReservationStatus.ACTIVE&&expiresAt.isBefore(Instant.now()))setStatus(ReservationStatus.EXPIRED);}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getUserId(){return userId;}public UUID getChargerId(){return chargerId;}public UUID getConnectorId(){return connectorId;}public String getReference(){return reference;}public ReservationStatus getStatus(){return status;}public Instant getStartsAt(){return startsAt;}public Instant getExpiresAt(){return expiresAt;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
